const STORE='vigyan-darshan-v3';let state={language:'bi',progress:[],scores:{},mistakes:{},lastChapter:'matter',selectedClass:'9',scienceSubject:'physics',speed:1,fontSize:17,theme:'system',scoreTotals:{},lastChapterByClass:{}};
try{state={...state,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{}
