 button('printAll','Print full book','पूरी पुस्तक प्रिंट करें');$('printAll').disabled=!chapters.length;button('printChapter','Print chapter','अध्याय प्रिंट करें');$('doneLabel').innerHTML=label('Mark chapter complete','अध्याय पूरा चिह्नित करें');
 $('sceneLabel').innerHTML=label('Choose a scene','दृश्य चुनें');button('restart','↺ Restart','↺ पुनः शुरू');button('resetView','⟳ Reset view','⟳ मूल दृश्य');
 $('showLabelsText').innerHTML=label('Show labels','नाम दिखाएँ');$('lowPowerText').innerHTML=label('Low power · 30 fps','कम ऊर्जा · 30 fps');$('lowPower').checked=state.lowPower;
 title('settingsHeading',B('Settings','सेटिंग'));$('fontSizeLabel').innerHTML=label('Text size','अक्षर आकार');
 $('interactionHint').textContent=text(B('Drag or use arrow keys to rotate. Scroll, pinch, or use + / − keys to zoom.','घुमाने के लिए खींचें या तीर-कुंजियाँ दबाएँ। पास-दूर करने के लिए स्क्रॉल, पिंच या + / − कुंजियों का उपयोग करें।'));
 title('lookHeading',B('What to look at','क्या देखना है'));title('realHeading',B('In everyday life','दैनिक जीवन में'));button('readNotes','Read detailed notes →','विस्तृत नोट्स पढ़ें →');
 title('tryHeading',B('Try this','यह करके देखें'));button('whyButton','Why?','ऐसा क्यों?');title('whyHeading',B('The science behind it','इसके पीछे का विज्ञान'));button('compareStates','Compare states','अवस्थाओं की तुलना');
 title('quickHeading',B('Quick check','त्वरित जाँच'));button('previous','← Previous chapter','← पिछला अध्याय');button('next','Next chapter →','अगला अध्याय →');title('drawerTitle',B('Chapters','अध्याय'));
