function initSceneState(){const s=S();return {values:s.controls.map(c=>c.initial),extra:{...(s.parameters||{}),...Object.fromEntries(s.selectors.map(s=>[s.id,s.options[0].value]))},quick:null,moved:false,completed:[],why:false,compare:false}}
