function condition(when){if(!when)return true;const actual=when.selector?sceneState.extra[when.selector]:sceneState.values[when.control??0],target=when.value;return when.op==='lte'?actual<=target:when.op==='gte'?actual>=target:when.op==='lt'?actual<target:when.op==='gt'?actual>target:Math.abs(actual-target)<1e-7}
function updateExploration(){const s=S(),v=sceneState;for(const m of s.missions||[])if(condition(m.when)&&!v.completed.includes(m.id))v.completed.push(m.id);$('missions').innerHTML=(s.missions||[]).map(m=>`<li class="mission ${v.completed.includes(m.id)?'completed':''}"><span aria-hidden="true">${v.completed.includes(m.id)?'✓':'○'}</span><span>${escape(text(m.label))}</span><span class="sr">${v.completed.includes(m.id)?escape(both(B('Completed','पूरा'))):''}</span></li>`).join('');const live=s.liveText?.find(item=>condition(item.when));$('liveText').textContent=text(live?.text||s.goal)}
function observe(moved=false){if(moved)sceneState.moved=true;if(sceneReady)lab.setValues(sceneState.values,sceneState.extra);updateExploration();quick()}
function pick(i){if(S().kind!=='organelles')return;const changed=sceneState.values[0]!==i;sceneState.values[0]=i;controls();observe(changed)}
function quick(){let s=S(),v=sceneState;$('quickCard').hidden=!v.moved;$('quickCheck').innerHTML=`<legend>${escape(text(s.quick.question))}</legend>`+s.quick.options.map((o,i)=>`<label class="radio"><input type="radio" name="quick" value="${i}" ${v.quick===i?'checked':''}>${escape(text(o))}</label>`).join('');$('quickFeedback').textContent=v.quick===null?'':text(v.quick===s.quick.correct?B('✓ Correct. ','✓ सही। '):B('Try again. ','फिर प्रयास करें। '))+text(s.quick.reason);$('quickCheck').querySelectorAll('input').forEach(el=>el.onchange=()=>{v.quick=Number(el.value);quick()})}
let flashTimer;
function flashThreshold(s,i,before,after){let events=[];if(s.kind==='heating'&&i===0)events=[{v:.42,en:'Melting point reached!',hi:'गलनांक पहुँचा'},{v:7.94,en:'Boiling point reached!',hi:'क्वथनांक पहुँचा'}];if(before*after<=0&&before!==after&&s.controls[i].min<0)events.push({v:0,en:'Zero crossed!',hi:'शून्य पार किया'});if(s.kind==='twelve-physics'&&s.parameters?.mode===19&&i===0)events=[{v:1/(2*Math.PI*Math.sqrt(.1*.0001)),en:'Resonance crossed!',hi:'अनुनाद आवृत्ति पार की'}];const e=events.find(e=>(before<e.v&&after>=e.v)||(before>e.v&&after<=e.v));if(!e)return;const node=$('thresholdFlash');clearTimeout(flashTimer);node.textContent=state.language==='bi'?both(B(e.en,e.hi)):text(B(e.en,e.hi));node.classList.remove('flash');void node.offsetWidth;node.classList.add('flash');flashTimer=setTimeout(()=>{node.textContent='';node.classList.remove('flash')},1500)}
